-- Identity, households and profiles.
--
-- Conventions (docs/PLAN.md §5):
-- - UUID v7 primary keys, generated by the application (Hibernate).
-- - timestamptz for every instant, stored in UTC.
-- - Enum-like columns are lowercase strings guarded by a check constraint.
-- - Every household table carries household_id with on delete cascade, so deleting a household
--   deletes all of its data (GDPR account deletion, docs/PLAN.md §8).
-- - Lists of short strings are jsonb arrays; their maximum sizes are validated in Java.

create table app_user (
    id           uuid         primary key,
    email        varchar(320) not null,
    display_name varchar(100) not null,
    locale       varchar(2)   not null check (locale in ('fr', 'nl', 'en')),
    created_at   timestamptz  not null default now()
);

-- Case-insensitive uniqueness: "Ju@x.com" and "ju@x.com" are the same person.
create unique index app_user_email_uk on app_user (lower(email));

create table household (
    id         uuid         primary key,
    name       varchar(100) not null,
    created_at timestamptz  not null default now()
);

create table household_member (
    household_id uuid        not null references household (id) on delete cascade,
    user_id      uuid        not null references app_user (id) on delete cascade,
    role         varchar(10) not null check (role in ('owner', 'member')),
    joined_at    timestamptz not null default now(),
    primary key (household_id, user_id),
    -- v1: a person belongs to a single household (docs/SCOPE.md).
    constraint household_member_user_uk unique (user_id)
);

create table household_invitation (
    id           uuid        primary key,
    household_id uuid        not null references household (id) on delete cascade,
    -- SHA-256 of the invitation token. The token itself is never stored: a database leak
    -- does not give access to any household.
    token_hash   bytea       not null unique check (octet_length(token_hash) = 32),
    created_by   uuid        references app_user (id) on delete set null,
    created_at   timestamptz not null default now(),
    expires_at   timestamptz not null,
    used_at      timestamptz,
    used_by      uuid        references app_user (id) on delete set null
);

create index household_invitation_household_idx on household_invitation (household_id);

-- Personal data: follows the person, not the household (docs/SCOPE.md).
create table person_profile (
    user_id                 uuid          primary key references app_user (id) on delete cascade,
    diet                    varchar(200),
    -- Health data (GDPR art. 9): explicit consent required before storing anything here.
    allergies               jsonb         not null default '[]' check (jsonb_typeof(allergies) = 'array'),
    dislikes                jsonb         not null default '[]' check (jsonb_typeof(dislikes) = 'array'),
    notes                   varchar(2000),
    onboarding_completed_at timestamptz,
    updated_at              timestamptz   not null default now()
);

create table household_profile (
    household_id       uuid          primary key references household (id) on delete cascade,
    table_size         smallint      check (table_size between 1 and 20),
    goals              jsonb         not null default '[]' check (jsonb_typeof(goals) = 'array'),
    goals_note         varchar(1000),
    budget             varchar(200),
    max_active_minutes smallint      check (max_active_minutes between 1 and 600),
    staples            jsonb         not null default '[]' check (jsonb_typeof(staples) = 'array'),
    notes              varchar(2000),
    updated_at         timestamptz   not null default now()
);
